async function invokeUserAdmin(payload){const {data,error}=await state.client.functions.invoke('invite-user',{body:payload});if(!error&&!data?.error)return data;if(data?.error)throw new Error(data.error);let detail=msg(error),status=error?.context?.status;try{const body=await error?.context?.clone?.().json();if(body?.error)detail=body.error}catch{}if(status===404)detail='O serviço de usuários ainda não foi publicado no Supabase. A implantação automática precisa ser configurada.';else if(status===401)detail='Sua sessão expirou. Entre novamente como administrador.';throw new Error(detail)}

function pretty(v){if(v===null||v===undefined||v==='')return '—';if(typeof v==='object')return JSON.stringify(v);return String(v)}
async function renderHistory(reset=true){if(reset){state.revisions=[];state.revisionOffset=0}const from=state.revisionOffset;const {data,error}=await state.client.from('record_revisions').select('id,actor_id,action,entity,entity_id,before_data,after_data,occurred_at').order('occurred_at',{ascending:false}).range(from,from+99);if(error)throw error;const page=data||[];state.revisions.push(...page);state.revisionOffset+=page.length;const rows=state.revisions;const actors=[...new Set(rows.map(r=>r.actor_id).filter(Boolean))];let emails={};if(actors.length){const {data:profiles}=await state.client.from('profiles').select('id,email').in('id',actors);for(const p of profiles||[])emails[p.id]=p.email}frame('<div class="page-intro"><div><h1>Histórico e versões</h1><p>Restaure uma versão anterior ou limpe o histórico.</p></div><button class="button danger" data-clear-history>Limpar histórico</button></div><div class="notice">A limpeza apaga as versões registradas e não pode ser desfeita.</div><div class="revision-list">'+(rows.length?rows.map(r=>{const before=r.before_data||{},after=r.after_data||{};const keys=[...new Set([...Object.keys(before),...Object.keys(after)])].filter(k=>!['id','created_by','created_at','updated_by','updated_at'].includes(k)&&JSON.stringify(before[k])!==JSON.stringify(after[k]));const target=after.full_name||before.full_name||after.plate||before.plate||r.entity_id;return '<details class="revision"><summary><span><strong>'+esc(target)+'</strong><small>'+esc(r.entity)+' · '+esc(r.action)+' · '+esc(emails[r.actor_id]||'usuário removido')+' · '+new Date(r.occurred_at).toLocaleString('pt-BR')+'</small></span><span class="revision-id">#'+r.id+'</span></summary><div class="revision-body">'+(keys.length?'<div class="diff-list">'+keys.map(k=>'<div class="diff-row"><strong>'+esc(k.replaceAll('_',' '))+'</strong><span>'+esc(pretty(before[k]))+'</span><span>→ '+esc(pretty(after[k]))+'</span></div>').join('')+'</div>':'<p>Cadastro criado ou sem campos alterados.</p>')+'<button class="button small" data-revert="'+r.id+'">Restaurar versão anterior</button></div></details>'}).join(''):'<div class="empty">Nenhuma alteração registrada ainda.</div>')+'</div>'+(page.length===100?'<button class="button secondary load-more" data-load-more>Carregar histórico anterior</button>':'') )}
function field(label,name,value='',type='text',full=false,attrs=''){
  const control=type==='textarea'?'<textarea id="f-'+name+'" name="'+name+'" '+attrs+'>'+esc(value)+'</textarea>':'<input id="f-'+name+'" name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+attrs+'>';
  return '<div class="field '+(full?'full':'')+'"><label for="f-'+name+'">'+label+'</label>'+control+'</div>';
}
function maskCpf(value){const digits=String(value||'').replace(/\\D/g,'');return digits.length===11?'***.***.***-'+digits.slice(-2):'—'}
async function lookupSimilarPeople(name,birthday='',rg=''){const {data,error}=await state.client.rpc('find_similar_people',{search_name:name,search_birthday:birthday||null,search_rg:rg||null});if(!error)return data||[];const fallback=await state.client.from('people').select('id,full_name,rg,birthday,cpf_digits,registration').is('archived_at',null).ilike('full_name',name).limit(8);if(fallback.error)throw fallback.error;return fallback.data||[]}
