async function uploadPhoto(entity,id,file){const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';const path=entity+'/'+id+'/'+crypto.randomUUID()+'.'+ext;const {error:upError}=await state.client.storage.from('people-photos').upload(path,file,{contentType:file.type,upsert:false});if(upError){toast('Registro salvo, mas a foto não foi enviada: '+msg(upError));return}const {data:existing,error:listError}=await state.client.from('record_photos').select('id').eq('entity',entity).eq('entity_id',id).limit(1);if(listError){toast('Foto enviada, mas a galeria precisa da migração 002.');return}const isCover=!existing?.length;const {error}=await state.client.from('record_photos').insert({entity,entity_id:id,photo_path:path,is_cover:isCover,created_by:state.session.user.id});if(error){toast('Foto enviada, mas não foi vinculada: '+msg(error));return}if(isCover){const table=entity;const {error:coverError}=await state.client.from(table).update({photo_path:path,updated_by:state.session.user.id}).eq('id',id);if(coverError)toast('Foto salva, mas não foi marcada como capa: '+msg(coverError))}}
