function openPhotoCropEditor(button){const id=button.dataset.photoAdjust,image=button.closest('.photo-item')?.querySelector('.photo-zoom img');if(!id||!image)return;const starting=photoPosition(button.dataset.photoPosition||image.style.objectPosition),parts=starting.match(/([\\d.]+)%\\s+([\\d.]+)%/);let x=Number(parts?.[1]||50),y=Number(parts?.[2]||50);const dialog=document.createElement('dialog');dialog.id='photoCropDialog';dialog.className='crop-editor-dialog';dialog.innerHTML='<div class="crop-editor-content"><div class="dialog-head"><div><h2>Ajustar enquadramento</h2><p>Arraste a imagem com o botão esquerdo do mouse. O recorte acompanha o movimento com precisão.</p></div><button type="button" class="close" data-crop-cancel aria-label="Fechar">×</button></div><div class="crop-stage" role="application" aria-label="Arraste a imagem para ajustar o enquadramento"></div><div class="crop-actions"><button type="button" class="button secondary" data-crop-cancel>Cancelar</button><button type="button" class="button" data-crop-save>Salvar enquadramento</button></div></div>';document.body.append(dialog);const stage=dialog.querySelector('.crop-stage'),preview=document.createElement('img'),bounds=image.parentElement.getBoundingClientRect();stage.style.aspectRatio=Math.max(1,bounds.width)+' / '+Math.max(1,bounds.height);preview.src=image.currentSrc||image.src;preview.alt='Prévia do enquadramento da foto';preview.draggable=false;const render=()=>{preview.style.objectPosition=x+'% '+y+'%'};render();stage.append(preview);let dragging=false,lastX=0,lastY=0;const clamp=value=>Math.max(0,Math.min(100,value));const overflow=()=>{const rect=stage.getBoundingClientRect(),width=image.naturalWidth||preview.naturalWidth,height=image.naturalHeight||preview.naturalHeight;if(!width||!height)return {x:0,y:0};const scale=Math.max(rect.width/width,rect.height/height);return {x:Math.max(0,width*scale-rect.width),y:Math.max(0,height*scale-rect.height)}};stage.addEventListener('pointerdown',event=>{if(event.button!==0)return;dragging=true;lastX=event.clientX;lastY=event.clientY;stage.classList.add('dragging');stage.setPointerCapture(event.pointerId);event.preventDefault()});stage.addEventListener('pointermove',event=>{if(!dragging)return;const dx=event.clientX-lastX,dy=event.clientY-lastY;lastX=event.clientX;lastY=event.clientY;const excess=overflow();if(excess.x>0)x=clamp(x-dx/excess.x*100);if(excess.y>0)y=clamp(y-dy/excess.y*100);render()});const stopDrag=()=>{dragging=false;stage.classList.remove('dragging')};stage.addEventListener('pointerup',stopDrag);stage.addEventListener('pointercancel',stopDrag);stage.addEventListener('lostpointercapture',stopDrag);dialog.querySelectorAll('[data-crop-cancel]').forEach(cancel=>cancel.onclick=()=>dialog.close());dialog.querySelector('[data-crop-save]').onclick=async()=>{const value=x.toFixed(2)+'% '+y.toFixed(2)+'%';const save=dialog.querySelector('[data-crop-save]');save.disabled=true;if(await setPhotoCrop(id,value,image,button))dialog.close();else save.disabled=false};dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal()}
